"considerably":{a:[{tr:"z. önemli ölçüde, hayli",ex:"The new treatment considerably reduced recovery time for patients suffering from chronic pain.",exTr:"Yeni tedavi, kronik ağrı çeken hastalarda iyileşme süresini önemli ölçüde azalttı."}],kl:[{en:"considerably higher",tr:"hayli yüksek"},{en:"vary considerably",tr:"önemli ölçüde değişmek"},{en:"increase considerably",tr:"önemli ölçüde artmak"}]},
"dry":{a:[{tr:"s. kuru, kurak",ex:"Crops that survive in dry climates are becoming increasingly valuable as global temperatures rise.",exTr:"Küresel sıcaklıklar yükseldikçe, kurak iklimlerde yaşayabilen tarım bitkileri giderek daha değerli hale geliyor.",yz:4},{tr:"f. kurumak, kurutmak",ex:"Farmers spread the harvested grain outside so it could dry completely before being stored in silos.",exTr:"Çiftçiler, silolarda depolanmadan önce tamamen kuruması için hasat edilen tahılı dışarıya serdi.",yz:2}],kl:[{en:"dry up",tr:"kurumak, tükenmek"},{en:"keep sth dry",tr:"bir şeyi kuru tutmak"},{en:"the dry season",tr:"kurak mevsim, yağışsız dönem"}]},
