"acid":{a:[{tr:"i. asit",ex:"Industrial emissions containing sulfur dioxide can combine with rainwater to form damaging acid rain.",exTr:"Kükürt dioksit içeren endüstriyel emisyonlar, yağmur suyuyla birleşerek zarar verici asit yağmuru oluşturabilir.",yz:4},{tr:"s. asitli, ekşi",ex:"The lemon left an acid taste in his mouth that lingered long after breakfast.",exTr:"Limon, kahvaltıdan çok sonra bile ağzında kalan ekşi bir tat bıraktı.",yz:2}],kl:[{en:"acid rain",tr:"asit yağmuru"}]},
"assess":{a:[{tr:"f. değerlendirmek, tahmin etmek, belirlemek",ex:"Inspectors were sent to assess the damage caused by the flood before repairs could begin.",exTr:"Onarımlara başlanabilmesi için müfettişler, selin neden olduğu hasarı değerlendirmek üzere gönderildi.",exs:[{"ex":"The evaluation will assess whether the new service reaches the communities for which it was originally designed.","exTr":"Değerlendirme, yeni hizmetin başlangıçta hedeflediği topluluklara ulaşıp ulaşmadığını inceleyecek."},{"ex":"Before extending the pilot scheme, the council asked an independent team to assess its costs and its effects on journey times.","exTr":"Belediye meclisi, pilot uygulamayı genişletmeden önce bağımsız bir ekipten uygulamanın maliyetlerini ve yolculuk süreleri üzerindeki etkilerini değerlendirmesini istedi."}]}],es:"evaluate, appraise",kl:[{en:"assess the impact of sth",tr:"bir şeyin etkisini değerlendirmek"},{en:"assess the risks",tr:"riskleri değerlendirmek"}]},
"birth":{a:[{tr:"i. doğum",ex:"Improved medical care has significantly lowered birth complications in many developing countries.",exTr:"Gelişmiş tıbbi bakım, birçok gelişmekte olan ülkede doğum komplikasyonlarını önemli ölçüde azalttı.",yz:4},{tr:"f. doğurmak",ex:"Doctors expect the endangered panda to birth twin cubs sometime next spring.",exTr:"Doktorlar, nesli tükenmekte olan pandanın önümüzdeki ilkbaharda ikiz yavru doğurmasını bekliyor.",yz:1}],kl:[{en:"give birth to sth",tr:"doğurmak, doğum yapmak"},{en:"at birth",tr:"doğuşta, doğduğunda"},{en:"the birth rate",tr:"doğum oranı"}]},
"ethnic":{a:[{tr:"s. etnik",ex:"Large cities often bring together people from many different ethnic and cultural backgrounds.",exTr:"Büyük şehirler, çoğu zaman birçok farklı etnik ve kültürel geçmişten insanları bir araya getirir."}],kl:[{en:"an ethnic minority",tr:"etnik azınlık"},{en:"an ethnic group",tr:"etnik köken grubu"}]},
"hunting":{a:[{tr:"avcılık, av",ex:"Illegal hunting has pushed several elephant populations to the edge of extinction.",exTr:"Yasa dışı avcılık, birçok fil popülasyonunu yok olmanın eşiğine getirdi."}],kl:[{en:"go hunting",tr:"ava çıkmak"},{en:"job hunting",tr:"iş arama"},{en:"hunting and gathering",tr:"avcılık ve toplayıcılık"}]},
"incorporate":{a:[{tr:"f. dahil etmek, birleştirmek",ex:"Architects now incorporate energy-saving features into the design of most new buildings.",exTr:"Mimarlar artık çoğu yeni binanın tasarımına enerji tasarrufu sağlayan özellikler dahil ediyor.",yz:4},{tr:"s. birleşmiş, tüzel",ex:"The charter refers to the university as an incorporate body founded in 1451.",exTr:"Berat, üniversiteden 1451'de kurulmuş tüzel bir birlik olarak söz eder.",yz:1}],es:"include, integrate",kl:[{en:"incorporate sth into sth",tr:"bir şeyi bir şeye dahil etmek"},{en:"be incorporated into sth",tr:"bir şeye dahil edilmek"}]},
"integrate":{a:[{tr:"f. bütünleştirmek, entegre etmek",ex:"Schools are working to integrate digital literacy into every subject rather than teaching it separately.",exTr:"Okullar, dijital okuryazarlığı ayrı bir ders olarak öğretmek yerine her derse entegre etmeye çalışıyor."}],es:"combine, merge",kl:[{en:"integrate sth into sth",tr:"bir şeyi bir şeye entegre etmek"},{en:"integrate with sth",tr:"bir şeyle bütünleşmek"},{en:"integrate into society",tr:"topluma uyum sağlamak"}]},
"minute":{a:[{tr:"s. çok küçük, ayrıntılı",ex:"Even a minute change in temperature can affect the outcome of a delicate chemical reaction.",exTr:"Sıcaklıktaki çok küçük bir değişiklik bile hassas bir kimyasal reaksiyonun sonucunu etkileyebilir.",yz:4},{tr:"i. dakika",ex:"The train departs in exactly one minute, so passengers should board immediately.",exTr:"Tren tam bir dakika içinde kalkıyor, bu yüzden yolcuların hemen binmesi gerekiyor.",yz:2}],kl:[{en:"in minute detail",tr:"en ince ayrıntısıyla"},{en:"a ten-minute break",tr:"on dakikalık mola"}]},
"motion":{a:[{tr:"i. hareket, devinim",ex:"Newton's laws describe the motion of objects under the influence of various forces.",exTr:"Newton yasaları, çeşitli kuvvetlerin etkisi altındaki cisimlerin hareketini tanımlar.",yz:4},{tr:"i. önerge",ex:"The committee voted to reject the motion to postpone the annual meeting until next spring.",exTr:"Komite, yıllık toplantıyı gelecek ilkbahara ertelemeye yönelik önergeyi reddetmek için oy kullandı.",yz:2}],kl:[{en:"set sth in motion",tr:"bir şeyi harekete geçirmek"},{en:"in slow motion",tr:"ağır çekimde"}]},
"prominent":{a:[{tr:"önde gelen, tanınmış",ex:"Several prominent scientists signed an open letter warning about the risks of artificial intelligence.",exTr:"Önde gelen birkaç bilim insanı, yapay zekânın riskleri konusunda uyarıda bulunan açık bir mektup imzaladı.",yz:4},{tr:"belirgin",ex:"The old sailor had a prominent scar across his left cheek from an accident at sea.",exTr:"Yaşlı denizcinin, denizde geçirdiği bir kazadan kalma sol yanağında belirgin bir yara izi vardı.",yz:3}],es:"leading, conspicuous",kl:[{en:"play a prominent role",tr:"önemli bir rol oynamak"},{en:"a prominent figure",tr:"önde gelen bir isim"}]},
"regulation":{a:[{tr:"i. düzenleme, yönetmelik",ex:"Strict environmental regulation has forced factories to reduce their harmful emissions significantly.",exTr:"Sıkı çevre düzenlemeleri, fabrikaları zararlı emisyonlarını önemli ölçüde azaltmaya zorlamıştır.",yz:4},{tr:"s. standart, kurallara uygun",ex:"Every player on the team must wear regulation equipment approved by the national sports federation.",exTr:"Takımdaki her oyuncu, ulusal spor federasyonu tarafından onaylanmış standart ekipman giymek zorundadır.",yz:1}],kl:[{en:"comply with regulations",tr:"düzenlemelere uymak"},{en:"safety regulations",tr:"güvenlik yönetmelikleri"},{en:"government regulation",tr:"devlet düzenlemesi"}]},
"statistic":{a:[{tr:"i. istatistik, istatistiksel veri",ex:"One alarming statistic shows that nearly a third of the region's coral reefs have already died.",exTr:"Endişe verici bir istatistik, bölgedeki mercan resiflerinin neredeyse üçte birinin çoktan öldüğünü gösteriyor."}],kl:[{en:"according to statistics",tr:"istatistiklere göre"},{en:"statistics show that",tr:"istatistikler şunu gösteriyor"}]},
