"wear":{a:[{tr:"f. giymek, takmak",ex:"Construction workers must wear protective helmets at all times on the building site.",exTr:"İnşaat işçileri şantiyede her an koruyucu baret takmak zorundadır.",yz:4},{tr:"aşındırmak; i. aşınma",ex:"Constant use had caused significant wear on the machine's metal gears over the years.",exTr:"Sürekli kullanım, yıllar içinde makinenin metal dişlilerinde önemli aşınmaya neden olmuştu.",yz:2}],kl:[{en:"wear glasses",tr:"gözlük takmak"},{en:"wear out",tr:"yıpranmak, eskimek"},{en:"wear and tear",tr:"yıpranma, aşınma"}]},
"background":{a:[{tr:"i. arka plan, geçmiş, altyapı",ex:"Employers often check a candidate's background before offering a position of financial responsibility.",exTr:"İşverenler, mali sorumluluk gerektiren bir pozisyon teklif etmeden önce genellikle adayın geçmişini kontrol eder."}],kl:[{en:"in the background",tr:"arka planda"},{en:"family background",tr:"aile geçmişi"},{en:"background information",tr:"arka plan bilgisi"}]},
"brief":{a:[{tr:"s. kısa, özlü",ex:"The lawyer gave a brief summary of the case before the judge asked further questions.",exTr:"Avukat, yargıç daha fazla soru sormadan önce davanın kısa bir özetini sundu.",yz:4},{tr:"f. bilgilendirmek, bilgi vermek",ex:"The officials were briefed about the outbreak before the press conference began.",exTr:"Yetkililer, basın toplantısı başlamadan önce salgın hakkında bilgilendirildi.",yz:3}],kl:[{en:"brief sb on sth",tr:"birine bir konuda bilgi vermek"},{en:"in brief",tr:"kısaca"},{en:"a brief period",tr:"kısa bir dönem"}]},
"comprise":{a:[{tr:"f. oluşmak, kapsamak; oluşturmak",ex:"Coral reefs comprise thousands of tiny organisms living together in a single structure.",exTr:"Mercan resifleri, tek bir yapı içinde birlikte yaşayan binlerce küçük organizmadan oluşur."}],es:"consist of, include",kl:[{en:"comprise several parts",tr:"birkaç bölümden oluşmak"},{en:"be comprised of sth",tr:"bir şeyden oluşmak"}]},
"formal":{a:[{tr:"s. resmi, biçimsel",ex:"The committee requires a formal written request before approving any changes to the curriculum.",exTr:"Komite, müfredatta herhangi bir değişikliği onaylamadan önce resmi bir yazılı talep istiyor.",yz:4},{tr:"i. resmi davet, balo",ex:"Every senior at the school looked forward to attending the winter formal with their closest friends.",exTr:"Okuldaki her son sınıf öğrencisi, en yakın arkadaşlarıyla kış balosuna katılmayı dört gözle bekliyordu.",yz:1}],kl:[{en:"formal education",tr:"örgün eğitim"},{en:"a formal agreement",tr:"resmi bir anlaşma"}]},
