"mature":{a:[{tr:"s. olgun, yetişkin",ex:"Mature students often bring valuable work experience into the university classroom.",exTr:"Yetişkin öğrenciler, üniversite sınıfına çoğu zaman değerli iş deneyimi getirir.",yz:4},{tr:"f. olgunlaşmak",ex:"Some tree species take more than fifty years to fully mature in the wild.",exTr:"Bazı ağaç türlerinin doğal ortamda tamamen olgunlaşması elli yıldan fazla sürer.",yz:3}],kl:[{en:"a mature student",tr:"yetişkin öğrenci"},{en:"mature into an adult",tr:"olgunlaşıp yetişkin olmak"}]},
"portion":{a:[{tr:"i. kısım, bölüm; porsiyon; pay",ex:"A significant portion of the national budget is devoted to healthcare and education services.",exTr:"Ulusal bütçenin önemli bir kısmı, sağlık ve eğitim hizmetlerine ayrılıyor."}],kl:[{en:"a large portion of sth",tr:"bir şeyin büyük bölümü"},{en:"a small portion",tr:"küçük bir porsiyon"}]},
