"grant":{a:[{tr:"f. vermek, bahşetmek; kabul etmek",ex:"The court granted the company permission to build a new factory near the river despite local objections.",exTr:"Mahkeme, yerel itirazlara rağmen şirkete nehrin yakınında yeni bir fabrika inşa etme izni verdi.",yz:4},{tr:"i. hibe, burs",ex:"The university received a substantial grant to study the effects of pollution on children's health.",exTr:"Üniversite, kirliliğin çocuk sağlığı üzerindeki etkilerini incelemek için önemli miktarda hibe aldı.",yz:3}],kl:[{en:"take sth for granted",tr:"bir şeyi olağan saymak"},{en:"grant sb access to sth",tr:"birine erişim izni vermek"},{en:"apply for a grant",tr:"hibeye başvurmak"}]},
"minimal":{a:[{tr:"s. asgari, minimum",ex:"The new surgical technique causes minimal damage to surrounding tissue compared with older methods.",exTr:"Yeni cerrahi teknik, eski yöntemlere kıyasla çevre dokuda asgari düzeyde hasara yol açıyor."}],kl:[{en:"with minimal effort",tr:"en az çabayla"},{en:"minimal impact",tr:"asgari düzeyde etki"}]},
"road":{a:[{tr:"i. yol",ex:"The government invested heavily in road infrastructure to connect remote rural villages.",exTr:"Hükümet, uzak kırsal köyleri birbirine bağlamak için yol altyapısına büyük yatırım yaptı."}],kl:[{en:"on the road",tr:"yolda, yol üstünde"},{en:"by road",tr:"karayoluyla"},{en:"the road to recovery",tr:"iyileşme yolu"}]},
"roman":{a:[{tr:"i. dik yazı karakteri (italik olmayan)",ex:"Most academic journals require manuscripts to be typed in roman rather than italic script.",exTr:"Çoğu akademik dergi, makalelerin italik yerine dik yazı karakteriyle yazılmasını şart koşar.",yz:3},{tr:"s. Roma'ya ait",ex:"Archaeologists uncovered several Roman coins buried beneath the ancient city ruins.",exTr:"Arkeologlar, antik şehir kalıntılarının altında gömülü birkaç Roma'ya ait sikke buldu.",yz:1}],kl:[{en:"roman numerals",tr:"Roma rakamları"},{en:"in roman type",tr:"dik yazı karakteriyle"}]},
"saying":{a:[{tr:"i. söz, deyiş, atasözü",ex:"An old saying among sailors warns that a red sky at dawn signals a coming storm.",exTr:"Denizciler arasındaki eski bir söz, şafakta kızıl gökyüzünün yaklaşan bir fırtınanın habercisi olduğunu söyler."}],kl:[{en:"as the saying goes",tr:"atasözünün dediği gibi"},{en:"an old saying",tr:"eski bir söz"}]},
