"vehicle":{a:[{tr:"i. araç, taşıt",ex:"Electric vehicles are expected to make up nearly half of new car sales by 2030.",exTr:"Elektrikli araçların, 2030 yılına kadar yeni araba satışlarının neredeyse yarısını oluşturması bekleniyor."}],kl:[{en:"a motor vehicle",tr:"motorlu taşıt"},{en:"a vehicle for change",tr:"değişim aracı"}]},
"coming":{a:[{tr:"s. gelecek, yaklaşan",ex:"Farmers are preparing for the coming winter by storing extra grain and fuel supplies.",exTr:"Çiftçiler, fazladan tahıl ve yakıt stoklayarak yaklaşan kışa hazırlanıyor.",yz:4},{tr:"i. geliş, gelme",ex:"The coming of spring brought a welcome burst of color to the previously grey mountainside.",exTr:"İlkbaharın gelişi, daha önce gri olan dağ yamacına hoş bir renk patlaması getirdi.",yz:1}],kl:[{en:"in the coming weeks",tr:"önümüzdeki haftalarda"},{en:"the coming years",tr:"gelecek yıllar"}]},
"elaborate":{a:[{tr:"s. ayrıntılı, özenli",ex:"Medieval cathedrals were decorated with elaborate carvings that took craftsmen decades to complete.",exTr:"Orta Çağ katedralleri, zanaatkârların tamamlaması on yıllar süren ayrıntılı oymalarla süslenirdi.",yz:4},{tr:"f. detaylandırmak, ayrıntıya girmek",ex:"The professor was asked to elaborate on his controversial theory during the conference.",exTr:"Profesörden, konferans sırasında tartışmalı teorisini detaylandırması istendi.",yz:3}],es:"detailed; expand on",kl:[{en:"elaborate on sth",tr:"bir şeyi ayrıntılandırmak"},{en:"an elaborate plan",tr:"ayrıntılı bir plan"}]},
"eyes":{a:[{tr:"i. gözler",ex:"Doctors recommend regular eye examinations because early damage to the eyes often produces no noticeable symptoms.",exTr:"Doktorlar düzenli göz muayenesini önerir çünkü gözlerdeki erken hasar genellikle fark edilir bir belirti vermez.",yz:4},{tr:"i. bakış, görüş (birinin gözünde)",ex:"In the eyes of many economists, rising inequality threatens long-term social stability.",exTr:"Birçok ekonomistin gözünde artan eşitsizlik, uzun vadeli toplumsal istikrarı tehdit ediyor.",yz:3}],kl:[{en:"in the eyes of sb",tr:"birinin gözünde"},{en:"open sb's eyes to sth",tr:"birinin gözünü açmak"}]},
