"immune":{a:[{tr:"s. bağışık, muaf",ex:"Vaccinated individuals are largely immune to the virus that caused last winter's outbreak.",exTr:"Aşılanmış bireyler, geçen kışki salgına yol açan virüse karşı büyük ölçüde bağışıktır."}],kl:[{en:"immune to sth",tr:"bir şeye karşı bağışık"},{en:"the immune system",tr:"bağışıklık sistemi"},{en:"immune from prosecution",tr:"kovuşturmadan muaf"}]},
"indeed":{a:[{tr:"z. gerçekten, hakikaten",ex:"The data indeed confirm that vaccination rates strongly correlate with lower infection levels.",exTr:"Veriler, aşılama oranlarının düşük enfeksiyon düzeyleriyle güçlü biçimde ilişkili olduğunu gerçekten doğruluyor."}],kl:[{en:"very good indeed",tr:"gerçekten çok iyi"}]},
"instrument":{a:[{tr:"i. alet, araç",ex:"The telescope remains the most important instrument for studying distant galaxies.",exTr:"Teleskop, uzak galaksileri incelemek için hâlâ en önemli araçtır.",yz:4},{tr:"çalgı",ex:"Every child in the orchestra learned to play a different instrument before the age of ten.",exTr:"Orkestradaki her çocuk, on yaşına gelmeden farklı bir çalgı çalmayı öğrendi.",yz:2}],kl:[{en:"a musical instrument",tr:"müzik aleti"},{en:"play an instrument",tr:"bir çalgı çalmak"},{en:"an instrument of change",tr:"değişim aracı"}]},
"meaningful":{a:[{tr:"s. anlamlı",ex:"Researchers found no meaningful difference in recovery times between the two treatment groups.",exTr:"Araştırmacılar, iki tedavi grubu arasındaki iyileşme sürelerinde anlamlı bir fark bulamadı."}],kl:[{en:"a meaningful relationship",tr:"anlamlı bir ilişki"},{en:"in a meaningful way",tr:"anlamlı bir biçimde"}]},
"perfect":{a:[{tr:"s. mükemmel, kusursuz",ex:"Meteorologists said the weekend weather would be nearly perfect for the outdoor music festival.",exTr:"Meteorologlar, hafta sonu havasının açık hava müzik festivali için neredeyse mükemmel olacağını söyledi.",yz:4},{tr:"f. mükemmelleştirmek",ex:"Years of daily practice helped the pianist perfect her technique before the international competition.",exTr:"Yıllar süren günlük çalışma, piyanistin uluslararası yarışma öncesinde tekniğini mükemmelleştirmesini sağladı.",yz:2}],kl:[{en:"perfect for sth",tr:"bir şey için mükemmel"},{en:"a perfect example",tr:"kusursuz bir örnek"},{en:"perfect a technique",tr:"bir tekniği mükemmelleştirmek"}]},
"phase":{a:[{tr:"i. evre, aşama, safha",ex:"The clinical trial has now entered its final phase, involving over ten thousand volunteers.",exTr:"Klinik deney, on binden fazla gönüllüyü kapsayan son evresine girmiş bulunuyor.",yz:4},{tr:"f. aşamalı olarak uygulamak",ex:"The government will phase the new tax in over a period of three years.",exTr:"Hükümet yeni vergiyi üç yıllık bir süreye yayarak aşamalı olarak uygulayacak.",yz:1}],kl:[{en:"phase sth out",tr:"bir şeyi aşamalı olarak kaldırmak"},{en:"the final phase",tr:"son aşama"},{en:"in phases",tr:"aşamalar halinde"}]},
