"burn":{a:[{tr:"f. yanmak, yakmak",ex:"Forest fires burn millions of hectares of woodland across the globe every year.",exTr:"Orman yangınları her yıl dünya genelinde milyonlarca hektarlık ormanlık alanı yakıyor.",yz:4},{tr:"i. yanık",ex:"The nurse carefully treated the severe burn on the patient's arm with a cooling gel.",exTr:"Hemşire, hastanın kolundaki ciddi yanığı soğutucu bir jelle dikkatle tedavi etti.",yz:2}],kl:[{en:"burn fat",tr:"yağ yakmak"},{en:"burn down a building",tr:"bir binayı yakıp yıkmak"},{en:"burn out",tr:"tükenmek"}]},
"direction":{a:[{tr:"i. yön",ex:"Migrating birds rely on the Earth's magnetic field to determine the correct direction to fly.",exTr:"Göçmen kuşlar, uçacakları doğru yönü belirlemek için Dünya'nın manyetik alanına güvenir.",yz:4},{tr:"i. yönetim, idare",ex:"The orchestra flourished under the direction of a conductor who encouraged young musicians to perform unfamiliar works.",exTr:"Orkestra, genç müzisyenleri alışılmadık eserleri seslendirmeye teşvik eden bir şefin yönetimi altında gelişti.",yz:2}],kl:[{en:"in the direction of sth",tr:"bir şeyin yönünde, bir şeye doğru"},{en:"in the right direction",tr:"doğru yönde"},{en:"under the direction of sb",tr:"birinin yönetiminde"}]},
"diversity":{a:[{tr:"i. çeşitlilik, farklılık",ex:"Rainforests contain an extraordinary diversity of plant and animal species found nowhere else.",exTr:"Yağmur ormanları, başka hiçbir yerde bulunmayan olağanüstü bir bitki ve hayvan türü çeşitliliği barındırır."}],kl:[{en:"cultural diversity",tr:"kültürel çeşitlilik"},{en:"biological diversity",tr:"biyolojik çeşitlilik"},{en:"a diversity of opinions",tr:"görüş çeşitliliği"}]},
"kept":{a:[{tr:"s. tutulmuş, yerine getirilmiş",ex:"A faithfully kept promise between nations can strengthen diplomatic trust for generations.",exTr:"Uluslar arasında sadakatle tutulan bir söz, diplomatik güveni nesiller boyu güçlendirebilir.",yz:3},{tr:"s. korunmuş, muhafaza edilmiş",ex:"The well kept garden behind the old manor attracted visitors from across the region every spring.",exTr:"Eski malikanenin arkasındaki iyi korunmuş bahçe, her bahar bölgenin dört bir yanından ziyaretçi çekiyordu.",yz:2}],kl:[{en:"be kept informed",tr:"bilgilendirilmek"},{en:"kept under control",tr:"denetim altında tutulan"}]},
"reverse":{a:[{tr:"f. tersine çevirmek, iptal etmek",ex:"Researchers hope the new therapy can reverse some of the damage caused by the disease.",exTr:"Araştırmacılar, yeni tedavinin hastalığın neden olduğu hasarın bir kısmını tersine çevirebilmesini umuyor.",yz:4},{tr:"s. ters, zıt",ex:"On the return journey, the expedition followed the same route in the reverse direction.",exTr:"Dönüş yolculuğunda sefer ekibi, aynı güzergâhı ters yönde izledi.",yz:3}],kl:[{en:"reverse a decision",tr:"bir kararı geri almak"},{en:"in reverse order",tr:"ters sırayla"}]},
