"novel":{a:[{tr:"s. yeni, özgün",ex:"Researchers have developed a novel method for detecting early signs of Alzheimer's disease.",exTr:"Araştırmacılar, Alzheimer hastalığının erken belirtilerini saptamak için yeni bir yöntem geliştirdi.",yz:4},{tr:"i. roman",ex:"The author spent nearly a decade writing her latest novel, which explores themes of memory and loss.",exTr:"Yazar, bellek ve kayıp temalarını işleyen son romanını yazmak için neredeyse on yıl harcadı.",yz:3}],kl:[{en:"a novel approach",tr:"özgün bir yaklaşım"},{en:"a best-selling novel",tr:"çok satan bir roman"}]},
"permanent":{a:[{tr:"s. kalıcı, daimi",ex:"Severe sunburn during childhood can cause permanent damage to the skin.",exTr:"Çocuklukta geçirilen şiddetli güneş yanığı, ciltte kalıcı hasara neden olabilir.",yz:4},{tr:"i. perma",ex:"She had a permanent done before the wedding and regretted it immediately.",exTr:"Düğünden önce perma yaptırdı ve hemen pişman oldu.",yz:1}],kl:[{en:"a permanent solution",tr:"kalıcı bir çözüm"},{en:"permanent damage",tr:"kalıcı hasar"},{en:"permanent residence",tr:"kalıcı oturma izni"}]},
