"smell":{a:[{tr:"f. koklamak; koku almak/vermek",ex:"Sharks can smell tiny traces of blood in the water from a remarkable distance.",exTr:"Köpekbalıkları, sudaki çok küçük kan izlerini şaşırtıcı bir uzaklıktan koklayabilir.",yz:3},{tr:"i. koku",ex:"A strange smell filled the kitchen after the milk had been left out overnight.",exTr:"Süt gece boyunca dışarıda bırakıldıktan sonra mutfağı garip bir koku kapladı.",yz:2}],kl:[{en:"smell of sth",tr:"bir şey gibi kokmak"},{en:"a strong smell",tr:"ağır, keskin bir koku"}]},
