"costs":{a:[{tr:"i. maliyetler, masraflar",ex:"Hospital administrators are searching for ways to reduce costs without lowering the quality of care.",exTr:"Hastane yöneticileri, bakım kalitesini düşürmeden maliyetleri azaltmanın yollarını arıyor."}],kl:[{en:"at all costs",tr:"ne pahasına olursa olsun"},{en:"cut costs",tr:"maliyetleri kısmak"},{en:"rising costs",tr:"artan maliyetler"}]},
"fine":{a:[{tr:"s. ince, güzel, iyi",ex:"The tailor used a fine silk fabric to make the wedding dress look elegant.",exTr:"Terzi, gelinliğin zarif görünmesi için ince bir ipek kumaş kullandı.",yz:3},{tr:"f. cezalandırmak, para cezası kesmek",ex:"The city plans to fine drivers who leave their engines running in no-idling zones.",exTr:"Şehir, motorunu rölantide çalışır bırakan sürücülere ceza kesmeyi planlıyor.",yz:1}],kl:[{en:"pay a fine",tr:"para cezası ödemek"},{en:"impose a fine on sb",tr:"birine para cezası kesmek"},{en:"the fine details",tr:"ince ayrıntılar"}]},
"flower":{a:[{tr:"i. çiçek",ex:"She placed a single fresh flower on the kitchen windowsill every Sunday morning.",exTr:"Her pazar sabahı mutfak pencere pervazına tek bir taze çiçek koyardı.",yz:4},{tr:"f. çiçek açmak",ex:"Botanists observed that the rare plant tends to flower only once every several years.",exTr:"Botanikçiler, nadir bitkinin genellikle birkaç yılda yalnızca bir kez çiçek açtığını gözlemledi.",yz:2}],kl:[{en:"in full flower",tr:"tam çiçek açmış"},{en:"a bunch of flowers",tr:"bir demet çiçek"}]},
"latter":{a:[{tr:"i. ikincisi",ex:"Given the choice between coal and solar power, most experts prefer the latter.",exTr:"Kömür ile güneş enerjisi arasında bir seçim söz konusu olduğunda uzmanların çoğu ikincisini tercih eder."}],kl:[{en:"the latter option",tr:"ikinci seçenek"},{en:"in the latter half",tr:"ikinci yarıda"}]},
"programme":{a:[{tr:"i. program",ex:"The university launched a new programme to encourage students to pursue careers in engineering.",exTr:"Üniversite, öğrencileri mühendislik alanında kariyer yapmaya teşvik etmek için yeni bir program başlattı.",yz:4},{tr:"f. programlamak",ex:"Technicians had to programme the new machine before it could operate safely on the factory floor.",exTr:"Teknisyenler, fabrika zemininde güvenle çalışabilmesi için yeni makineyi programlamak zorunda kaldı.",yz:2}],kl:[{en:"a training programme",tr:"eğitim programı"},{en:"a television programme",tr:"televizyon programı"}]},
