"summer":{a:[{tr:"i. yaz",ex:"Extreme summer heat has forced several cities to open public cooling centers for residents.",exTr:"Aşırı yaz sıcakları, birçok kenti sakinleri için halka açık soğutma merkezleri açmak zorunda bıraktı.",yz:4},{tr:"f. yazı geçirmek",ex:"The family has summered on the same coastal island for over thirty years.",exTr:"Aile, otuz yılı aşkın bir süredir aynı sahil adasında yazlarını geçiriyor.",yz:1}],kl:[{en:"in summer",tr:"yazın"},{en:"the summer months",tr:"yaz ayları"}]},
"basically":{a:[{tr:"z. temelde, esasen, aslında",ex:"The proposed reform is basically an attempt to modernize the outdated healthcare system.",exTr:"Önerilen reform, temelde eski sağlık sistemini modernize etme girişimidir."}],kl:[{en:"basically the same",tr:"temelde aynı"},{en:"basically unchanged",tr:"esasen değişmemiş"}]},
