"overlap":{a:[{tr:"i. çakışma, örtüşme",ex:"The researchers noticed a significant overlap between climate change and public health concerns.",exTr:"Araştırmacılar, iklim değişikliği ile halk sağlığı endişeleri arasında önemli bir örtüşme fark etti.",yz:3},{tr:"f. çakışmak, örtüşmek",ex:"The two lectures overlap by thirty minutes, so students must choose which one to attend.",exTr:"İki ders otuz dakika çakışıyor, bu yüzden öğrenciler hangisine katılacaklarını seçmek zorunda.",yz:3}],kl:[{en:"overlap with sth",tr:"bir şeyle örtüşmek"},{en:"a considerable overlap",tr:"hatırı sayılır bir örtüşme"},{en:"overlap between the two",tr:"ikisi arasındaki çakışma"}]},
"park":{a:[{tr:"i. park",ex:"The city converted an abandoned railway line into a long, narrow public park.",exTr:"Kent, terk edilmiş bir demiryolu hattını uzun ve dar bir kamu parkına dönüştürdü.",yz:3},{tr:"f. park etmek",ex:"Visitors are asked not to park their vehicles near the main entrance.",exTr:"Ziyaretçilerden araçlarını ana girişin yakınına park etmemeleri isteniyor.",yz:2}],kl:[{en:"park the car",tr:"arabayı park etmek"},{en:"a national park",tr:"milli park"}]},
