"noise":{a:[{tr:"i. gürültü, ses",ex:"Constant traffic noise in large cities can lead to stress and sleep disorders.",exTr:"Büyük şehirlerdeki sürekli trafik gürültüsü, strese ve uyku bozukluklarına yol açabilir.",yz:4},{tr:"f. (noise about/abroad) yaymak, ortalığa duyurmak",ex:"Rumours of the merger were noised abroad long before any official statement appeared.",exTr:"Birleşme söylentileri, resmî bir açıklama çıkmadan çok önce ortalığa yayılmıştı.",yz:1}],kl:[{en:"make a noise",tr:"gürültü yapmak"},{en:"background noise",tr:"arka plan gürültüsü"},{en:"noise pollution",tr:"gürültü kirliliği"}]},
